#version 300 es
in vec3 position;
in vec3 normal;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 baseColor;
uniform float gain;
uniform vec3 sunDir;
uniform vec3 sunColor;
uniform vec3 ambient;
